function StepPrerequisites{Section 'Validating Android prerequisites';foreach($c in @('dotnet','java','keytool')){if(-not(Get-Command $c -ErrorAction SilentlyContinue)){throw "$c not found in PATH."}};$v=(& dotnet --version).Trim();if($LASTEXITCODE -ne 0 -or -not $v.StartsWith('10.')){throw "Requires .NET SDK 10; detected $v"};Log "Detected .NET SDK: $v" Success;& java -version 2>&1|ForEach-Object{Log "$_"};if($LASTEXITCODE -ne 0){throw 'Java execution failed.'};$sdk=$env:ANDROID_HOME;if(-not $sdk){$sdk=$env:ANDROID_SDK_ROOT};if(-not $sdk -or -not(Test-Path -LiteralPath $sdk -PathType Container)){throw 'ANDROID_HOME or ANDROID_SDK_ROOT must point to an existing Android SDK.'};$p=Join-Path $script:Cfg.Root $script:Cfg.Project;if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "Project not found: $p"};Log "Android SDK: $sdk" Success}
